--
-- Name: sp_auto_close_missing_jobs(smallint, bigint, timestamp with time zone); Type: FUNCTION; Schema: silver; Owner: -
--

CREATE FUNCTION silver.sp_auto_close_missing_jobs(p_source_id smallint, p_session_id bigint, p_session_start_time timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_closed_count INT := 0;
BEGIN
    -- Chỉ thực hiện nếu session này thành công (có data)
    -- Để tránh lỗi scraper bị block làm đóng hết job
    IF NOT EXISTS (
        SELECT 1 FROM silver.crawl_sessions
        WHERE session_id = p_session_id AND total_validated > 10
    ) THEN
        RETURN 0;
    END IF;

    -- 1. Tăng not_found_count cho các job không thấy trong session này
    UPDATE silver.jobs
    SET not_found_count = not_found_count + 1
    WHERE source_id = p_source_id
      AND is_active = TRUE
      AND last_seen_at < p_session_start_time;

    -- 2. Đóng các job có not_found_count >= 3
    -- (Tối ưu: dùng CTE Returning để log event)
    WITH closed_jobs AS (
        UPDATE silver.jobs
        SET job_status = 'CLOSED',
            is_active = FALSE,
            closed_at = NOW(),
            inactive_reason = 'Not found 3 consecutive times'
        WHERE source_id = p_source_id
          AND is_active = TRUE
          AND not_found_count >= 3
        RETURNING job_id
    )
    SELECT job_id, 'STATUS_CLOSED', p_source_id, p_session_id, 'Auto closed: Not found 3 times', NOW()
    FROM closed_jobs;

    GET DIAGNOSTICS v_closed_count = ROW_COUNT;

    RETURN v_closed_count;
END;
$$;


--
-- Name: sp_auto_expire_deadline(); Type: FUNCTION; Schema: silver; Owner: -
--

CREATE FUNCTION silver.sp_auto_expire_deadline() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_expired_count INT := 0;
BEGIN
    WITH expired_jobs AS (
        SELECT j.job_id
        FROM silver.jobs j
        JOIN silver.job_snapshots s ON j.job_id = s.job_id AND s.is_current = TRUE
        WHERE j.is_active = TRUE
          AND s.deadline_date < CURRENT_DATE
    ),
    update_jobs AS (
        UPDATE silver.jobs j
        SET job_status = 'EXPIRED',
            is_active = FALSE,
            expired_at = NOW(),
            inactive_reason = 'Auto expired based on deadline'
        FROM expired_jobs e
        WHERE j.job_id = e.job_id
        RETURNING j.job_id
    )
    SELECT job_id, 'STATUS_EXPIRED', 'Auto expired: past deadline date', NOW()
    FROM update_jobs;

    GET DIAGNOSTICS v_expired_count = ROW_COUNT;

    RETURN v_expired_count;
END;
$$;


--
-- Name: sp_process_staging_batch(bigint, date); Type: PROCEDURE; Schema: silver; Owner: -
--

CREATE PROCEDURE silver.sp_process_staging_batch(IN p_session_id bigint, IN p_batch_date date DEFAULT CURRENT_DATE)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_processed_count INT;
BEGIN
    RAISE INFO 'Starting optimized batch processing for session_id: %, batch_date: %', p_session_id, p_batch_date;

    -- 1. Bulk insert các company mới từ staging (không trùng lặp normalized_name)
    SELECT DISTINCT company_normalized, company_raw
    FROM staging.stg_jobs
    WHERE batch_date = p_batch_date
      AND company_normalized IS NOT NULL
    ON CONFLICT (normalized_name) DO NOTHING;

    -- 2. Bulk insert company aliases
    SELECT DISTINCT c.company_id, stg.company_raw, src.source_id, 100
    FROM staging.stg_jobs stg
    JOIN silver.sources src ON stg.source_code = src.source_code
    JOIN silver.companies c ON stg.company_normalized = c.normalized_name
    WHERE stg.batch_date = p_batch_date
    ON CONFLICT (alias_text) DO NOTHING;

    -- 3. Bulk Upsert vào silver.jobs sử dụng CTE
    WITH upserted_jobs AS (
            source_id, company_id, source_job_id, canonical_url,
            identity_hash, latest_content_hash, job_status, is_active, first_seen_at, last_seen_at
        )
        SELECT 
            src.source_id,
            c.company_id,
            stg.source_job_id,
            stg.canonical_url,
            stg.identity_hash,
            stg.content_hash,
            'ACTIVE'::job_status_enum,
            TRUE,
            stg.scraped_at,
            stg.scraped_at
        FROM staging.stg_jobs stg
        JOIN silver.sources src ON stg.source_code = src.source_code
        JOIN silver.companies c ON stg.company_normalized = c.normalized_name
        WHERE stg.batch_date = p_batch_date
        ON CONFLICT (source_id, source_job_id) 
        DO UPDATE SET 
            last_seen_at = EXCLUDED.last_seen_at,
            not_found_count = 0,
            -- Nếu content hash thay đổi, cập nhật status để trigger SCD type 2 ở bước sau
            job_status = CASE WHEN silver.jobs.latest_content_hash != EXCLUDED.latest_content_hash THEN 'UPDATED'::job_status_enum ELSE silver.jobs.job_status END,
            latest_content_hash = EXCLUDED.latest_content_hash,
            updated_at = NOW()
        RETURNING job_id, source_job_id, latest_content_hash, (created_at = updated_at) AS is_new
    )
    SELECT COUNT(*) INTO v_processed_count FROM upserted_jobs;

    -- 4. Bulk xử lý SCD Type 2 Snapshots:
    -- Đóng các snapshot cũ nếu có cập nhật content hash
    UPDATE silver.job_snapshots js
    SET is_current = FALSE,
        valid_to = stg.scraped_at
    FROM staging.stg_jobs stg
    JOIN silver.sources src ON stg.source_code = src.source_code
    JOIN silver.jobs j ON j.source_id = src.source_id AND j.source_job_id = stg.source_job_id
    WHERE stg.batch_date = p_batch_date
      AND js.job_id = j.job_id
      AND js.is_current = TRUE
      AND j.latest_content_hash != js.content_hash;

    -- Insert các snapshot mới
        job_id, is_current, valid_from, version_number,
        title_raw, title_clean, description,
        salary_raw, salary_min, salary_max,
        experience_raw, experience_min_years, experience_max_years,
        job_level, job_type, work_mode, job_family,
        deadline_raw, deadline_date, is_intern, is_fresher, content_hash
    )
    SELECT 
        j.job_id,
        TRUE,
        stg.scraped_at,
        COALESCE(prev.version_number, 0) + 1,
        stg.title_raw, stg.title_clean, stg.description,
        stg.salary_raw, stg.salary_min, stg.salary_max,
        stg.experience_raw, stg.experience_min_years, stg.experience_max_years,
        stg.job_level, stg.job_type, stg.work_mode, stg.job_family,
        stg.deadline_raw, stg.deadline_date, stg.is_intern, stg.is_fresher, stg.content_hash
    FROM staging.stg_jobs stg
    JOIN silver.sources src ON stg.source_code = src.source_code
    JOIN silver.jobs j ON j.source_id = src.source_id AND j.source_job_id = stg.source_job_id
    LEFT JOIN silver.job_snapshots prev ON prev.job_id = j.job_id AND prev.valid_to = stg.scraped_at
    WHERE stg.batch_date = p_batch_date
      AND NOT EXISTS (
          SELECT 1 FROM silver.job_snapshots active 
          WHERE active.job_id = j.job_id AND active.is_current = TRUE AND active.content_hash = stg.content_hash
      );

    -- 5. Cập nhật crawl session stats
    UPDATE silver.crawl_sessions
    SET total_validated = v_processed_count
    WHERE session_id = p_session_id;

    RAISE INFO 'Batch processing complete. Processed % jobs.', v_processed_count;
END;
$$;


--
-- Name: sp_resolve_company(character varying, smallint); Type: FUNCTION; Schema: silver; Owner: -
--

CREATE FUNCTION silver.sp_resolve_company(p_company_raw character varying, p_source_id smallint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_company_id INT;
    v_normalized VARCHAR;
    v_alias_id INT;
BEGIN
    -- 1. Chuẩn hóa cơ bản (Bỏ TNHH, JSC, Co. Ltd...)
    -- Đơn giản hóa trong SQL, có thể viết logic phức tạp hơn ở dbt/Python
    v_normalized := TRIM(REGEXP_REPLACE(
        UPPER(p_company_raw),
        '\s*(CO\.\s*LTD|COMPANY LIMITED|TNHH|CỔ PHẦN|JSC|CORPORATION|CORP)\.?\s*$',
        '',
        'i'
    ));

    -- 2. Tìm trong company_aliases
    SELECT company_id INTO v_company_id
    FROM silver.company_aliases
    WHERE alias_text = p_company_raw;

    IF v_company_id IS NOT NULL THEN
        RETURN v_company_id;
    END IF;

    -- 3. Tìm trực tiếp trong companies theo normalized_name
    SELECT company_id INTO v_company_id
    FROM silver.companies
    WHERE normalized_name = v_normalized
    LIMIT 1;

    -- 4. Nếu chưa có, tạo company mới
    IF v_company_id IS NULL THEN
        VALUES (v_normalized, p_company_raw)
        RETURNING company_id INTO v_company_id;
    END IF;

    -- 5. Lưu lại alias mới để lần sau lookup nhanh hơn
    VALUES (v_company_id, p_company_raw, p_source_id, 100)
    ON CONFLICT (alias_text) DO NOTHING;

    RETURN v_company_id;
END;
$_$;


--
-- Name: sp_upsert_job(smallint, integer, character varying, text, character, character, text, text, text, character varying, numeric, numeric, character varying, smallint, smallint, public.job_level_enum, public.job_type_enum, public.work_mode_enum, character varying, character varying, date, boolean, boolean, text[], timestamp with time zone, bigint); Type: FUNCTION; Schema: silver; Owner: -
--

CREATE FUNCTION silver.sp_upsert_job(p_source_id smallint, p_company_id integer, p_source_job_id character varying, p_canonical_url text, p_identity_hash character, p_content_hash character, p_title_raw text, p_title_clean text, p_description text, p_salary_raw character varying, p_salary_min numeric, p_salary_max numeric, p_experience_raw character varying, p_experience_min smallint, p_experience_max smallint, p_job_level public.job_level_enum, p_job_type public.job_type_enum, p_work_mode public.work_mode_enum, p_job_family character varying, p_deadline_raw character varying, p_deadline_date date, p_is_intern boolean, p_is_fresher boolean, p_skills_raw text[], p_scraped_at timestamp with time zone, p_session_id bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_job_id BIGINT;
    v_current_content_hash CHAR(16);
    v_current_status job_status_enum;
    v_action VARCHAR;
    v_snapshot_id BIGINT;
    v_old_version SMALLINT;
    v_skill_name TEXT;
    v_skill_id INT;
BEGIN
    -- 1. Tìm job hiện tại (Khớp theo source_id + source_job_id HOẶC canonical_url)
    SELECT job_id, latest_content_hash, job_status
    INTO v_job_id, v_current_content_hash, v_current_status
    FROM silver.jobs
    WHERE (source_id = p_source_id AND source_job_id = p_source_job_id)
       OR (canonical_url = p_canonical_url)
    LIMIT 1;

    -- ==========================================
    -- CASE A: NEW JOB (Chưa từng tồn tại)
    -- ==========================================
    IF v_job_id IS NULL THEN
        -- A1. Insert vào jobs
            source_id, company_id, source_job_id, canonical_url,
            identity_hash, latest_content_hash, job_status, is_active, first_seen_at, last_seen_at
        ) VALUES (
            p_source_id, p_company_id, p_source_job_id, p_canonical_url,
            p_identity_hash, p_content_hash, 'ACTIVE', TRUE, p_scraped_at, p_scraped_at
        ) RETURNING job_id INTO v_job_id;

        -- A2. Insert vào job_snapshots (Version 1)
            job_id, is_current, valid_from, version_number,
            title_raw, title_clean, description,
            salary_raw, salary_min, salary_max,
            experience_raw, experience_min_years, experience_max_years,
            job_level, job_type, work_mode, job_family,
            deadline_raw, deadline_date, is_intern, is_fresher, content_hash
        ) VALUES (
            v_job_id, TRUE, p_scraped_at, 1,
            p_title_raw, p_title_clean, p_description,
            p_salary_raw, p_salary_min, p_salary_max,
            p_experience_raw, p_experience_min, p_experience_max,
            p_job_level, p_job_type, p_work_mode, p_job_family,
            p_deadline_raw, p_deadline_date, p_is_intern, p_is_fresher, p_content_hash
        ) RETURNING snapshot_id INTO v_snapshot_id;

        -- A3. Insert Skills (Tối ưu hóa bằng Set-Based Bulk Insert với UNNEST)
        IF p_skills_raw IS NOT NULL AND array_length(p_skills_raw, 1) > 0 THEN
            WITH target_skills AS (
                SELECT DISTINCT TRIM(s) AS skill_name, LOWER(TRIM(s)) AS skill_code
                FROM unnest(p_skills_raw) s
                WHERE TRIM(s) != ''
            ),
            inserted_skills AS (
                SELECT skill_code, skill_name FROM target_skills
                ON CONFLICT (skill_code) DO UPDATE SET display_name = EXCLUDED.display_name
                RETURNING skill_id, skill_code
            )
            SELECT v_snapshot_id, COALESCE(ins.skill_id, s.skill_id)
            FROM target_skills ts
            LEFT JOIN inserted_skills ins ON ts.skill_code = ins.skill_code
            LEFT JOIN silver.skills s ON ts.skill_code = s.skill_code
            ON CONFLICT DO NOTHING;
        END IF;

        -- A4. Log event
        VALUES (v_job_id, 'JOB_CREATED', p_source_id, p_session_id, p_scraped_at);

        RETURN 'NEW';
    END IF;

    -- ==========================================
    -- Tồn tại Job. Cập nhật last_seen_at trước.
    -- ==========================================
    UPDATE silver.jobs
    SET last_seen_at = p_scraped_at,
        not_found_count = 0 -- Reset not found
    WHERE job_id = v_job_id;

    -- Xử lý REOPENED nếu job đang đóng/hết hạn
    IF v_current_status IN ('CLOSED', 'EXPIRED', 'NOT_FOUND') THEN
        UPDATE silver.jobs
        SET job_status = 'ACTIVE',
            is_active = TRUE,
            inactive_reason = NULL,
            reopened_at = p_scraped_at
        WHERE job_id = v_job_id;

        VALUES (v_job_id, 'STATUS_REOPENED', p_source_id, p_session_id, 'Scraped again after being closed/expired', p_scraped_at);

        v_action := 'REOPENED';
    ELSE
        v_action := 'UNCHANGED';
    END IF;

    -- ==========================================
    -- CASE B: CONTENT UPDATED (SCD Type 2)
    -- ==========================================
    IF v_current_content_hash != p_content_hash THEN

        -- Lấy version hiện tại
        SELECT version_number INTO v_old_version
        FROM silver.job_snapshots
        WHERE job_id = v_job_id AND is_current = TRUE;

        -- B1. Đóng bản ghi snapshot cũ
        UPDATE silver.job_snapshots
        SET is_current = FALSE,
            valid_to = p_scraped_at
        WHERE job_id = v_job_id AND is_current = TRUE;

        -- B2. Insert snapshot mới
            job_id, is_current, valid_from, version_number,
            title_raw, title_clean, description,
            salary_raw, salary_min, salary_max,
            experience_raw, experience_min_years, experience_max_years,
            job_level, job_type, work_mode, job_family,
            deadline_raw, deadline_date, is_intern, is_fresher, content_hash
        ) VALUES (
            v_job_id, TRUE, p_scraped_at, COALESCE(v_old_version, 0) + 1,
            p_title_raw, p_title_clean, p_description,
            p_salary_raw, p_salary_min, p_salary_max,
            p_experience_raw, p_experience_min, p_experience_max,
            p_job_level, p_job_type, p_work_mode, p_job_family,
            p_deadline_raw, p_deadline_date, p_is_intern, p_is_fresher, p_content_hash
        ) RETURNING snapshot_id INTO v_snapshot_id;

        -- B3. Insert Skills cho Snapshot mới (Tối ưu hóa bằng Set-Based Bulk Insert với UNNEST)
        IF p_skills_raw IS NOT NULL AND array_length(p_skills_raw, 1) > 0 THEN
            WITH target_skills AS (
                SELECT DISTINCT TRIM(s) AS skill_name, LOWER(TRIM(s)) AS skill_code
                FROM unnest(p_skills_raw) s
                WHERE TRIM(s) != ''
            ),
            inserted_skills AS (
                SELECT skill_code, skill_name FROM target_skills
                ON CONFLICT (skill_code) DO UPDATE SET display_name = EXCLUDED.display_name
                RETURNING skill_id, skill_code
            )
            SELECT v_snapshot_id, COALESCE(ins.skill_id, s.skill_id)
            FROM target_skills ts
            LEFT JOIN inserted_skills ins ON ts.skill_code = ins.skill_code
            LEFT JOIN silver.skills s ON ts.skill_code = s.skill_code
            ON CONFLICT DO NOTHING;
        END IF;

        -- B4. Cập nhật latest hash vào jobs
        UPDATE silver.jobs
        SET latest_content_hash = p_content_hash,
            job_status = 'UPDATED'
        WHERE job_id = v_job_id;

        -- B5. Log event
        VALUES (v_job_id, 'CONTENT_UPDATED', p_source_id, p_session_id, 'Content hash changed', p_scraped_at);

        v_action := 'UPDATED';
    END IF;

    RETURN v_action;
END;
$$;


