--
-- Name: job_snapshots; Type: TABLE; Schema: silver; Owner: -
--

CREATE TABLE silver.job_snapshots (
    snapshot_id bigint NOT NULL,
    job_id bigint NOT NULL,
    is_current boolean DEFAULT true NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    version_number smallint DEFAULT 1 NOT NULL,
    title_raw text NOT NULL,
    title_clean text,
    description text,
    requirements text,
    salary_raw character varying(255),
    salary_min numeric(15,0),
    salary_max numeric(15,0),
    salary_avg numeric(15,0) GENERATED ALWAYS AS (
CASE
    WHEN ((salary_min IS NOT NULL) AND (salary_max IS NOT NULL)) THEN ((salary_min + salary_max) / (2)::numeric)
    ELSE COALESCE(salary_min, salary_max)
END) STORED,
    salary_currency character varying(10) DEFAULT 'VND'::character varying,
    salary_is_negotiable boolean DEFAULT false NOT NULL,
    experience_raw text,
    experience_min_years smallint,
    experience_max_years smallint,
    job_level public.job_level_enum DEFAULT 'UNKNOWN'::public.job_level_enum,
    job_type public.job_type_enum DEFAULT 'UNKNOWN'::public.job_type_enum,
    work_mode public.work_mode_enum DEFAULT 'UNKNOWN'::public.work_mode_enum,
    job_family character varying(100),
    deadline_raw text,
    deadline_date date,
    is_intern boolean DEFAULT false NOT NULL,
    is_fresher boolean DEFAULT false NOT NULL,
    is_no_experience boolean DEFAULT false NOT NULL,
    is_student_friendly boolean DEFAULT false NOT NULL,
    has_conflict_flag boolean DEFAULT false NOT NULL,
    content_hash character(16) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_snapshot_exp CHECK (((experience_min_years IS NULL) OR (experience_max_years IS NULL) OR (experience_min_years <= experience_max_years))),
    CONSTRAINT chk_snapshot_salary CHECK (((salary_min IS NULL) OR (salary_max IS NULL) OR (salary_min <= salary_max))),
    CONSTRAINT chk_snapshot_valid CHECK (((valid_to IS NULL) OR (valid_to > valid_from)))
);


--
-- Name: TABLE job_snapshots; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON TABLE silver.job_snapshots IS 'SCD Type 2: lịch sử nội dung tin tuyển dụng. Tạo bản ghi mới khi content_hash thay đổi.';


--
-- Name: COLUMN job_snapshots.is_current; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.job_snapshots.is_current IS 'TRUE = phiên bản đang có hiệu lực. Luôn chỉ có 1 bản TRUE / job_id';


--
-- Name: COLUMN job_snapshots.valid_to; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.job_snapshots.valid_to IS 'NULL = đang hiệu lực. Timestamp khi bị đóng bởi bản ghi mới hơn.';


--
-- Name: jobs; Type: TABLE; Schema: silver; Owner: -
--

CREATE TABLE silver.jobs (
    job_id bigint NOT NULL,
    source_id smallint NOT NULL,
    company_id integer NOT NULL,
    source_job_id text,
    canonical_url text,
    identity_hash character(16) NOT NULL,
    latest_content_hash character(16),
    job_status public.job_status_enum DEFAULT 'NEW'::public.job_status_enum NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    not_found_count smallint DEFAULT 0 NOT NULL,
    inactive_reason text,
    duplicate_group_id integer,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    expired_at timestamp with time zone,
    reopened_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_closed_at CHECK (((closed_at IS NULL) OR (closed_at >= first_seen_at))),
    CONSTRAINT chk_expired_at CHECK (((expired_at IS NULL) OR (expired_at >= first_seen_at))),
    CONSTRAINT jobs_not_found_count_check CHECK ((not_found_count >= 0))
);


--
-- Name: TABLE jobs; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON TABLE silver.jobs IS 'Thực thể tin tuyển dụng. Chỉ lưu định danh tĩnh + trạng thái. Nội dung ở job_snapshots.';


--
-- Name: COLUMN jobs.identity_hash; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.jobs.identity_hash IS 'SHA-256[:16] tính từ: source+company+location+job_family+salary_bucket+skills_sorted';


--
-- Name: COLUMN jobs.latest_content_hash; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.jobs.latest_content_hash IS 'Hash nội dung phiên bản hiện tại. Thay đổi → tạo snapshot mới (SCD Type 2)';


--
-- Name: COLUMN jobs.not_found_count; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.jobs.not_found_count IS 'Số lần quét liên tiếp không thấy tin. >= 3 → CLOSED';


--
-- Name: mv_active_jobs_summary; Type: MATERIALIZED VIEW; Schema: dwh; Owner: -
--

CREATE MATERIALIZED VIEW dwh.mv_active_jobs_summary AS
 SELECT f.silver_job_id AS job_id,
    c.silver_company_id AS company_id,
    ds.silver_source_id AS source_id,
    jb.canonical_url,
    jb.job_status,
    f.silver_snapshot_id AS snapshot_id,
    js.title_clean,
    f.salary_min_vnd AS salary_min,
    f.salary_max_vnd AS salary_max,
    f.salary_midpoint_vnd AS salary_avg,
    js.salary_currency,
    f.experience_min_years,
    f.experience_max_years,
    a.job_level,
    a.job_type,
    a.work_mode,
    js.job_family,
    (to_char((js.deadline_date)::timestamp with time zone, 'YYYYMMDD'::text))::integer AS deadline_date_key,
    f.is_intern,
    f.is_fresher,
    (to_char(jb.first_seen_at, 'YYYYMMDD'::text))::integer AS first_seen_date_key,
    (to_char(jb.last_seen_at, 'YYYYMMDD'::text))::integer AS last_seen_date_key,
    c.company_name,
    c.industry AS company_industry,
    c.company_name AS company_normalized_name
   FROM (((((dwh.fct_job_posting f
     JOIN dwh.dim_company c ON ((f.company_key = c.company_key)))
     JOIN dwh.dim_source ds ON ((f.source_key = ds.source_key)))
     JOIN dwh.dim_job_attributes a ON ((f.attribute_key = a.attribute_key)))
     JOIN silver.jobs jb ON ((f.silver_job_id = jb.job_id)))
     JOIN silver.job_snapshots js ON ((f.silver_snapshot_id = js.snapshot_id)))
  WHERE ((f.is_active = true) AND (js.is_current = true))
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_active_jobs_summary; Type: COMMENT; Schema: dwh; Owner: -
--

COMMENT ON MATERIALIZED VIEW dwh.mv_active_jobs_summary IS 'Cache tất cả jobs đang tuyển với company info denormalized. Refresh sau mỗi pipeline run.';


--
-- Name: mv_jobs_by_location; Type: MATERIALIZED VIEW; Schema: dwh; Owner: -
--

CREATE MATERIALIZED VIEW dwh.mv_jobs_by_location AS
 SELECT l.silver_location_id AS location_id,
    l.location_name AS location_code,
    l.location_name,
    l.region,
    false AS is_remote,
    count(f.silver_job_id) AS total_jobs,
    round(avg(f.salary_midpoint_vnd)) AS avg_salary,
    count(DISTINCT f.company_key) AS total_companies,
    count(
        CASE
            WHEN f.is_fresher THEN 1
            ELSE NULL::integer
        END) AS fresher_jobs
   FROM ((dwh.dim_location l
     JOIN dwh.bridge_job_location fjl ON ((l.location_key = fjl.location_key)))
     JOIN dwh.fct_job_posting f ON ((fjl.job_posting_fact_id = f.job_posting_fact_id)))
  WHERE (f.is_active = true)
  GROUP BY l.silver_location_id, l.location_name, l.region
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_jobs_by_location; Type: COMMENT; Schema: dwh; Owner: -
--

COMMENT ON MATERIALIZED VIEW dwh.mv_jobs_by_location IS 'Phân bổ job theo địa điểm. Dùng cho Power BI Map visualization.';


--
-- Name: mv_kpi_realtime; Type: MATERIALIZED VIEW; Schema: dwh; Owner: -
--

CREATE MATERIALIZED VIEW dwh.mv_kpi_realtime AS
 SELECT now() AS refreshed_at,
    count(f.silver_job_id) AS total_active_jobs,
    count(DISTINCT f.company_key) AS total_hiring_companies,
    round(avg(f.salary_midpoint_vnd)) AS market_avg_salary_vnd,
    percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((f.salary_midpoint_vnd)::double precision)) AS market_median_salary_vnd,
    round((((count(
        CASE
            WHEN (f.salary_midpoint_vnd IS NOT NULL) THEN 1
            ELSE NULL::integer
        END))::numeric * 100.0) / (NULLIF(count(*), 0))::numeric), 2) AS salary_disclosure_rate_pct,
    count(
        CASE
            WHEN (f.is_fresher OR ((a.job_level)::text = 'FRESHER'::text)) THEN 1
            ELSE NULL::integer
        END) AS total_fresher_jobs,
    count(
        CASE
            WHEN (f.is_intern OR ((a.job_level)::text = 'INTERN'::text)) THEN 1
            ELSE NULL::integer
        END) AS total_intern_jobs,
    count(
        CASE
            WHEN ((a.work_mode)::text = ANY ((ARRAY['REMOTE'::character varying, 'HYBRID'::character varying])::text[])) THEN 1
            ELSE NULL::integer
        END) AS total_remote_hybrid_jobs,
    count(
        CASE
            WHEN ((js.job_family)::text = 'DATA_ENGINEER'::text) THEN 1
            ELSE NULL::integer
        END) AS jobs_data_engineer,
    count(
        CASE
            WHEN ((js.job_family)::text = 'DATA_ANALYST'::text) THEN 1
            ELSE NULL::integer
        END) AS jobs_data_analyst,
    count(
        CASE
            WHEN ((js.job_family)::text = 'BACKEND'::text) THEN 1
            ELSE NULL::integer
        END) AS jobs_backend,
    count(
        CASE
            WHEN ((js.job_family)::text = 'FRONTEND'::text) THEN 1
            ELSE NULL::integer
        END) AS jobs_frontend,
    count(
        CASE
            WHEN ((js.job_family)::text = 'FULLSTACK'::text) THEN 1
            ELSE NULL::integer
        END) AS jobs_fullstack
   FROM ((dwh.fct_job_posting f
     JOIN dwh.dim_job_attributes a ON ((f.attribute_key = a.attribute_key)))
     JOIN silver.job_snapshots js ON ((f.silver_snapshot_id = js.snapshot_id)))
  WHERE (f.is_active = true)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_kpi_realtime; Type: COMMENT; Schema: dwh; Owner: -
--

COMMENT ON MATERIALIZED VIEW dwh.mv_kpi_realtime IS 'KPI thị trường real-time. Aligned với Semantic Layer metrics (sem_job_market.yml). Refresh concurrently.';


--
-- Name: mv_salary_by_skill; Type: MATERIALIZED VIEW; Schema: dwh; Owner: -
--

CREATE MATERIALIZED VIEW dwh.mv_salary_by_skill AS
 WITH skill_salary AS (
         SELECT sk.silver_skill_id AS skill_id,
            sk.skill_name AS skill_code,
            sk.skill_name,
            sk.skill_category,
            count(f.silver_job_id) AS job_count,
            avg(f.salary_midpoint_vnd) AS avg_salary,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((f.salary_midpoint_vnd)::double precision)) AS median_salary,
            min(f.salary_min_vnd) AS min_salary,
            max(f.salary_max_vnd) AS max_salary,
            count(
                CASE
                    WHEN (f.salary_midpoint_vnd IS NOT NULL) THEN 1
                    ELSE NULL::integer
                END) AS jobs_with_salary
           FROM ((dwh.bridge_job_skill fjs
             JOIN dwh.fct_job_posting f ON ((fjs.job_posting_fact_id = f.job_posting_fact_id)))
             JOIN dwh.dim_skill sk ON ((fjs.skill_key = sk.skill_key)))
          WHERE (f.is_active = true)
          GROUP BY sk.silver_skill_id, sk.skill_name, sk.skill_category
        )
 SELECT skill_id,
    skill_code,
    skill_name,
    skill_category,
    job_count,
    avg_salary,
    median_salary,
    min_salary,
    max_salary,
    jobs_with_salary,
    rank() OVER (ORDER BY avg_salary DESC NULLS LAST) AS salary_rank,
    rank() OVER (ORDER BY job_count DESC) AS demand_rank
   FROM skill_salary
  WHERE (job_count >= 5)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_salary_by_skill; Type: COMMENT; Schema: dwh; Owner: -
--

COMMENT ON MATERIALIZED VIEW dwh.mv_salary_by_skill IS 'Lương trung bình + median theo từng kỹ năng. Cache query nặng nhất của Power BI.';


--
-- Name: job_duplicate_groups; Type: TABLE; Schema: silver; Owner: -
--

CREATE TABLE silver.job_duplicate_groups (
    group_id integer NOT NULL,
    canonical_job_id bigint NOT NULL,
    group_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE job_duplicate_groups; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON TABLE silver.job_duplicate_groups IS 'Nhóm các tin tuyển dụng giống nhau từ nhiều nguồn khác nhau';


--
-- Name: COLUMN job_duplicate_groups.canonical_job_id; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.job_duplicate_groups.canonical_job_id IS 'Tin đại diện (canonical) của nhóm - thường là tin từ nguồn uy tín nhất';


--
-- Name: latest_jobs_flat; Type: MATERIALIZED VIEW; Schema: mart_api; Owner: -
--

CREATE MATERIALIZED VIEW mart_api.latest_jobs_flat AS
 SELECT f.silver_job_id AS id,
    j.title_clean AS job_title,
    c.company_name,
    c.industry,
    so.source_name,
    a.job_level,
    a.job_type,
    a.work_mode,
    j.salary_raw AS salary_display,
    f.salary_min_vnd,
    f.salary_max_vnd,
    f.experience_min_years,
    f.experience_max_years,
    j.deadline_date,
    jb.canonical_url,
    j.is_current,
    ARRAY( SELECT s.skill_name
           FROM (dwh.bridge_job_skill bjs
             JOIN dwh.dim_skill s ON ((s.skill_key = bjs.skill_key)))
          WHERE (bjs.job_posting_fact_id = f.job_posting_fact_id)) AS skills,
    ARRAY( SELECT l.location_name
           FROM (dwh.bridge_job_location bjl
             JOIN dwh.dim_location l ON ((l.location_key = bjl.location_key)))
          WHERE (bjl.job_posting_fact_id = f.job_posting_fact_id)) AS locations
   FROM ((((((dwh.fct_job_posting f
     JOIN silver.job_snapshots j ON ((f.silver_snapshot_id = j.snapshot_id)))
     JOIN silver.jobs jb ON ((j.job_id = jb.job_id)))
     JOIN dwh.dim_company c ON ((f.company_key = c.company_key)))
     JOIN dwh.dim_source so ON ((f.source_key = so.source_key)))
     JOIN dwh.dim_job_attributes a ON ((f.attribute_key = a.attribute_key)))
     LEFT JOIN silver.job_duplicate_groups dg ON ((jb.duplicate_group_id = dg.group_id)))
  WHERE ((f.is_active = true) AND (j.is_current = true) AND ((jb.duplicate_group_id IS NULL) OR (jb.job_id = dg.canonical_job_id)))
  WITH NO DATA;


