-- Name: COLUMN cdc_watermarks.last_sync_at; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.cdc_watermarks.last_sync_at IS 'Timestamp của batch đã được sync thành công gần nhất. Dùng làm filter cho lần chạy tiếp theo.';


--
-- Name: COLUMN cdc_watermarks.anomaly_flag; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.cdc_watermarks.anomaly_flag IS 'TRUE khi job_count < expected_min_count * 0.5. Cảnh báo scraper có thể bị block.';


