--
-- Name: crawl_sessions; Type: TABLE; Schema: silver; Owner: -
--

CREATE TABLE silver.crawl_sessions (
    session_id bigint NOT NULL,
    run_date date NOT NULL,
    source_id smallint,
    crawl_status public.crawl_status_enum DEFAULT 'RUNNING'::public.crawl_status_enum NOT NULL,
    total_scraped integer DEFAULT 0 NOT NULL,
    total_validated integer DEFAULT 0 NOT NULL,
    total_rejected integer DEFAULT 0 NOT NULL,
    rejection_rate numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (total_scraped > 0) THEN round((((total_rejected)::numeric / (total_scraped)::numeric) * (100)::numeric), 2)
    ELSE (0)::numeric
END) STORED,
    pages_scraped integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    duration_seconds integer GENERATED ALWAYS AS ((EXTRACT(epoch FROM (completed_at - started_at)))::integer) STORED
);


--
-- Name: TABLE crawl_sessions; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON TABLE silver.crawl_sessions IS 'Mỗi phiên crawl 1 source trong 1 ngày. Guard cho logic auto-close.';


--
-- Name: COLUMN crawl_sessions.rejection_rate; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON COLUMN silver.crawl_sessions.rejection_rate IS 'Tỷ lệ reject tự động tính. > 15% = cảnh báo';


