CREATE TABLE silver.pipeline_run_log (
    run_id bigint NOT NULL,
    pipeline_name character varying(100) DEFAULT 'daily_job_pipeline'::character varying NOT NULL,
    run_date date DEFAULT CURRENT_DATE NOT NULL,
    source_code character varying(50),
    stage character varying(50) NOT NULL,
    records_extracted integer DEFAULT 0 NOT NULL,
    records_new integer DEFAULT 0 NOT NULL,
    records_updated integer DEFAULT 0 NOT NULL,
    records_unchanged integer DEFAULT 0 NOT NULL,
    records_rejected integer DEFAULT 0 NOT NULL,
    watermark_from timestamp with time zone,
    watermark_to timestamp with time zone,
    status character varying(20) DEFAULT 'RUNNING'::character varying NOT NULL,
    error_message text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    duration_seconds integer GENERATED ALWAYS AS ((EXTRACT(epoch FROM (completed_at - started_at)))::integer) STORED,
    CONSTRAINT chk_run_status CHECK (((status)::text = ANY ((ARRAY['RUNNING'::character varying, 'SUCCESS'::character varying, 'FAILED'::character varying, 'SKIPPED'::character varying])::text[])))
)
PARTITION BY RANGE (run_date);


--
-- Name: TABLE pipeline_run_log; Type: COMMENT; Schema: silver; Owner: -
--

COMMENT ON TABLE silver.pipeline_run_log IS 'Log chi tiết mỗi lần chạy pipeline, partitioned theo ngày. Dùng để debug và monitor performance.';


