    location_normalized text,
    job_family text,
    deadline_date date,
    is_intern boolean DEFAULT false,
    is_fresher boolean DEFAULT false,
    identity_hash character(16) NOT NULL,
    content_hash character(16) NOT NULL,
    change_type character varying(20),
    scraped_at timestamp with time zone NOT NULL,
    processed_at timestamp with time zone DEFAULT now() NOT NULL,
    pipeline_version character varying(20) DEFAULT '2.0'::character varying NOT NULL,
    batch_date date DEFAULT CURRENT_DATE NOT NULL
);


